function assignBiomes(heightmap, temperatureMap, precipitationMap):
    for each pixel (x, y):
        temp = temperatureMap[x,y]
        precip = precipitationMap[x,y]
        alt = heightmap[x,y]

        // Adjust temperature for altitude
        adjustedTemp = temp - (alt * lapseRate)

        // Calculate scores for each biome
        bestBiome = null
        bestScore = -infinity

        for each biome in biomeLibrary:
            // Fuzzy membership function
            tempScore = gaussian(biome.optimalTemp, biome.tempRange, adjustedTemp)
            precipScore = gaussian(biome.optimalPrecip, biome.precipRange, precip)

            // Combine scores
            score = tempScore * precipScore * biome.probability

            if score > bestScore:
                bestScore = score
                bestBiome = biome

        // Add procedural variation
        noise = perlinNoise(x*0.01, y*0.01) * 0.2
        if bestScore + noise < threshold:
            bestBiome = getTransitionBiome(bestBiome, secondBestBiome)

        biomeMap[x,y] = bestBiome

    return biomeMap
